<script setup>
import {ref,reactive,computed,provide,toRef,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import WizardStepper from './WizardStepper.vue';
import StepFiles from './steps/StepFiles.vue';
import StepDetails from './steps/StepDetails.vue';
import StepCompat from './steps/StepCompat.vue';
import StepSummary from './steps/StepSummary.vue';
import SettingsIcon from './SettingsIcon.vue';
import {size} from '../lib/catalog';
import '../styles/product-wizard.css';
const props=defineProps({avatars:{type:Array,default:()=>[]},tagOptions:{type:Array,default:()=>[]}});const emit=defineEmits(['close','added']);
const form=reactive({name:'',category:'',avatars:[],tags:[],adult:false,generic:false,files:[],previewFile:null,previewUrl:'',autoName:false});
const step=ref(1),furthest=ref(1),editing=ref(false),direction=ref('forward'),dialog=ref(),discardDialog=ref(),body=ref(),busy=ref(false),error=ref(''),progress=ref(''),fileNotice=ref(''),token=ref(''),announcement=ref('');
let done=new Set(),previousFocus,discardFocus;
const stepNames=['Archivos','Detalles','Compatibilidad','Resumen'];const components=[StepFiles,StepDetails,StepCompat,StepSummary];
const frozen=computed(()=>busy.value||!!token.value);const totalSize=computed(()=>form.files.reduce((sum,f)=>sum+f.size,0));
const uploadFiles=computed(()=>form.previewFile?[new File([form.previewFile],'__preview.'+form.previewFile.name.split('.').pop().toLowerCase(),{type:form.previewFile.type}),...form.files]:form.files);
const detailsValid=computed(()=>!!form.name.trim()&&!!form.category);const valid=computed(()=>form.files.length>0&&detailsValid.value);
const stepValid=computed(()=>step.value===1?form.files.length>0:step.value===2?detailsValid.value:step.value===3?true:valid.value);
const dirty=computed(()=>!!(form.name||form.category||form.files.length||form.previewFile||form.avatars.length||form.tags.length||form.generic||form.adult));
const status=computed(()=>{if(busy.value)return progress.value||'Agregando…';if(step.value===1)return form.files.length?form.files.length+' archivos · '+size(totalSize.value):'Agregá al menos un archivo';if(step.value===2&&!detailsValid.value){const missing=[];if(!form.name.trim())missing.push('nombre');if(!form.category)missing.push('categoría');return 'Falta: '+missing.join(' y ');}if(step.value===4)return 'Revisá y confirmá. Podés editar cualquier sección.';return form.files.length+' archivos listos · '+size(totalSize.value);});
function clearPreview(){if(frozen.value)return;if(form.previewUrl)URL.revokeObjectURL(form.previewUrl);form.previewUrl='';form.previewFile=null;}
function setPreview(file){if(frozen.value||!file)return;if(!/\.(png|jpe?g|webp)$/i.test(file.name)){fileNotice.value='La portada debe ser JPG, PNG o WebP.';return;}clearPreview();form.previewFile=file;form.previewUrl=URL.createObjectURL(file);fileNotice.value='';error.value='';}
function autoComplete(){if(!form.name){const main=form.files.find(f=>/\.unitypackage$/i.test(f.name))||form.files.find(f=>/\.(zip|rar)$/i.test(f.name));if(main){form.name=main.name.replace(/\.[^.]+$/,'').replace(/_/g,' ');form.autoName=true;}}}
function addFiles(incoming){if(frozen.value)return;const notices=[];for(const file of incoming){if(form.files.some(f=>f.name.toLocaleLowerCase()===file.name.toLocaleLowerCase())){notices.push('«'+file.name+'» ya está en la lista.');continue;}if(/\.(exe|msi|bat|cmd|ps1|com|scr|lnk)$/i.test(file.name)||!file.name.includes('.')){notices.push('«'+file.name+'» no es un formato de recurso compatible.');continue;}if(form.previewFile&&file.name.toLowerCase()==='__preview.'+form.previewFile.name.split('.').pop().toLowerCase()){notices.push('Ese nombre está reservado para la portada.');continue;}form.files.push(file);}fileNotice.value=notices.join(' ');}
function canGo(target){if(target>=2&&!form.files.length)return false;if(target>=3&&!detailsValid.value)return false;return true;}
async function go(target){if(busy.value||target<1||target>4||!canGo(target))return;if(step.value===1&&target>1)autoComplete();direction.value=target<step.value?'backward':'forward';furthest.value=Math.max(furthest.value,target);step.value=target;announcement.value='Paso '+target+' de 4: '+stepNames[target-1];await nextTick();if(body.value)body.value.scrollTop=0;}
function editStep(target){if(frozen.value)return;editing.value=true;go(target);}
function stepperNavigate(target){if(target<=furthest.value&&!busy.value)go(target);}
function next(){if(busy.value||!stepValid.value)return;if(step.value===4){submit();return;}if(step.value===1)autoComplete();if(editing.value){if(valid.value){editing.value=false;go(4);}return;}go(step.value+1);}
function back(){if(busy.value)return;if(step.value===1)requestClose();else go(step.value-1);}
function requestClose(){if(busy.value)return;if(!dirty.value){emit('close');return;}discardFocus=document.activeElement;discardDialog.value.showModal();}
function keepEditing(){discardDialog.value.close();discardFocus?.focus();}
function backdrop(e){if(e.target!==dialog.value)return;const r=dialog.value.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)requestClose();}
function paste(e){if(step.value!==2||frozen.value||discardDialog.value?.open||e.target.closest('input,textarea,[contenteditable="true"]'))return;const image=[...e.clipboardData.items].find(item=>item.type.startsWith('image/'));if(image){e.preventDefault();setPreview(image.getAsFile());}}
function keys(e){if(discardDialog.value?.open||!dialog.value?.open)return;if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();if(!busy.value&&valid.value){if(step.value===4)submit();else{editing.value=false;go(4);}}return;}if(e.key==='Enter'&&!e.defaultPrevented&&!e.target.closest('button,[role="combobox"],[role="listbox"]')){e.preventDefault();next();}if(e.key==='Tab'){const controls=[...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(el=>el.getClientRects().length&&!el.hidden);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
async function request(url,options){const r=await fetch(url,options),data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo guardar');return data;}
async function submit(){if(busy.value||!valid.value||step.value!==4)return;busy.value=true;error.value='';try{
if(!token.value){const data=await request('/api/upload/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:form.name.trim(),category:form.category,avatars:form.avatars,tags:form.tags.join(', '),adult:form.adult,generic:form.generic,files:uploadFiles.value.map(f=>({name:f.name,size:f.size}))})});token.value=data.token;}
for(let i=0;i<uploadFiles.value.length;i++){const f=uploadFiles.value[i];if(done.has(f.name))continue;progress.value='Subiendo '+(i+1)+' de '+uploadFiles.value.length+': '+f.name;await request('/api/upload/file?token='+encodeURIComponent(token.value)+'&name='+encodeURIComponent(f.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:f});done.add(f.name);}
progress.value=window.__VRC_DESKTOP__?'Comprimiendo y verificando ZIP…':'Guardando producto…';const result=await request('/api/upload/finish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:token.value})});emit('added',result.path);
}catch(e){error.value=e.message;}finally{busy.value=false;}}
provide('productWizard',{form,frozen,addFiles,fileNotice,totalSize,setPreview,clearPreview,uploadFiles,editStep,avatarOptions:toRef(props,'avatars'),tagOptions:toRef(props,'tagOptions'),zipEnabled:Boolean(window.__VRC_DESKTOP__)});
async function focusStep(){await nextTick();const selector=step.value===1?'.wizard-step-files .product-drop-button':step.value===2?'#wizard-product-name':step.value===3?'.wizard-step-compat input':'.wizard-summary-preview h3';body.value?.querySelector(selector)?.focus();}
onMounted(async()=>{previousFocus=document.activeElement;dialog.value.showModal();document.addEventListener('paste',paste);document.addEventListener('keydown',keys);announcement.value='Paso 1 de 4: Archivos';await focusStep();});
onBeforeUnmount(()=>{document.removeEventListener('paste',paste);document.removeEventListener('keydown',keys);if(form.previewUrl)URL.revokeObjectURL(form.previewUrl);if(discardDialog.value?.open)discardDialog.value.close();if(dialog.value?.open)dialog.value.close();previousFocus?.focus();});
</script>
<template><dialog ref="dialog" class="product-wizard-dialog add-product-dialog mochi-night" :class="{'is-summary':step===4}" role="dialog" aria-modal="true" aria-labelledby="titulo-wizard" @cancel.prevent="requestClose" @click="backdrop"><form class="product-form" :aria-busy="busy" @submit.prevent="next"><header class="product-modal-header"><h2 id="titulo-wizard">Agregar producto</h2><button class="product-icon-button" type="button" :disabled="busy" aria-label="Cerrar" @click="requestClose"><SettingsIcon name="x"/></button></header><WizardStepper :step="step" :completed="furthest" :disabled="busy" @navigate="stepperNavigate"/><span class="wizard-sr-only" role="status" aria-live="polite">{{announcement}}</span><div ref="body" class="product-modal-body"><Transition :name="'wizard-'+direction" mode="out-in" @after-enter="focusStep"><component :is="components[step-1]" :key="step"/></Transition></div><div v-if="error" class="product-error-strip" role="alert">{{error}}</div><footer class="product-modal-footer wizard-footer"><button type="button" class="wizard-back" :disabled="busy" @click="back"><SettingsIcon v-if="step>1" name="chevron"/>{{step===1?'Cancelar':'Atrás'}}</button><span class="wizard-sr-only" aria-live="polite">{{status}}</span><button class="product-submit" type="submit" :disabled="busy||!stepValid"><SettingsIcon v-if="busy" name="refresh" class="product-spinner"/>{{busy?'Agregando…':step===4?(token?'Reintentar':'Agregar producto'):editing?'Volver al resumen':'Siguiente'}}<kbd v-if="step===4&&!busy">Ctrl+↵</kbd><SettingsIcon v-else-if="!busy" name="chevron"/></button></footer></form></dialog><dialog ref="discardDialog" class="product-discard-dialog mochi-night" aria-labelledby="wizard-discard-title" @cancel.prevent="keepEditing"><h3 id="wizard-discard-title">¿Descartar este producto?</h3><p>Tenés datos cargados. Si cerrás, perderás lo que todavía no guardaste.</p><p v-if="token">Los archivos que ya se enviaron permanecen en la carpeta de la biblioteca.</p><div><button type="button" class="product-cancel" @click="keepEditing">Seguir editando</button><button type="button" class="product-submit" @click="emit('close')">Descartar</button></div></dialog></template>
